import{_ as a,C as e,o as s,c as l,j as r,a as o,E as n,a2 as g}from"./chunks/framework.DGvnA5EY.js";const x=JSON.parse('{"title":"附录 C 小白说明书速查表（精简版）","description":"> 内容来源：WorkBuddy 官方指南（非官方整理，© 本指南作者，保留所有权利） 第一篇每章末尾都有一节「小白说明书」，把那一章的术语用人话讲一遍。读完就散了——想回头查\\"当初那个词什么意思\\"，得翻十几个章节。","frontmatter":{"title":"附录 C 小白说明书速查表（精简版）"},"headers":[],"relativePath":"bluebook/附录/附录 C 小白说明书速查表/index.md","filePath":"bluebook/附录/附录 C 小白说明书速查表/index.md","lastUpdated":1792135267000}'),i={name:"bluebook/附录/附录 C 小白说明书速查表/index.md"};function h(u,t,b,q,k,p){const d=e("Paywall");return s(),l("div",null,[t[0]||(t[0]=r("h1",{id:"附录-c-小白说明书速查表-精简版",tabindex:"-1"},[o("附录 C 小白说明书速查表（精简版） "),r("a",{class:"header-anchor",href:"#附录-c-小白说明书速查表-精简版","aria-label":'Permalink to "附录 C 小白说明书速查表（精简版）"'},"​")],-1)),n(d,{variant:"banner"}),t[1]||(t[1]=r("blockquote",null,[r("p",null,"内容来源：WorkBuddy 官方指南（非官方整理，© 本指南作者，保留所有权利）")],-1)),t[2]||(t[2]=r("h2",{id:"这份表是干什么的",tabindex:"-1"},[o("这份表是干什么的 "),r("a",{class:"header-anchor",href:"#这份表是干什么的","aria-label":'Permalink to "这份表是干什么的"'},"​")],-1)),t[3]||(t[3]=r("p",null,'第一篇每章末尾都有一节「小白说明书」，把那一章的术语用人话讲一遍。读完就散了——想回头查"当初那个词什么意思"，得翻十几个章节。',-1)),t[4]||(t[4]=r("p",null,[o("这份表把"),r("strong",null,"最常用的核心术语"),o("汇到一处，按主题分组，每组开头有字母索引，可 Ctrl+F 检索。")],-1)),n(d,{variant:"note"}),t[5]||(t[5]=g('<hr><h2 id="一、ai-是怎么工作的-先看这组" tabindex="-1">一、AI 是怎么工作的（先看这组） <a class="header-anchor" href="#一、ai-是怎么工作的-先看这组" aria-label="Permalink to &quot;一、AI 是怎么工作的（先看这组）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>术语</th><th>人话解释</th></tr></thead><tbody><tr><td><strong>AI Agent（智能体）</strong></td><td>能自己拆步骤、调工具、动手干活的 AI。&quot;代理&quot;就是替你做事——你交任务，它自己执行给你结果。</td></tr><tr><td><strong>提示词（Prompt）</strong></td><td>你给 AI 的那段话。说得越具体越不容易猜错。但 WorkBuddy 的思路是<strong>你讲清目标就行，不用自己拆步骤</strong>。</td></tr><tr><td><strong>工具调用（Tool Call）</strong></td><td>AI 自己&quot;伸手&quot;操作外部东西：打开 Excel、读网页、跑脚本。这个过程你能看到。</td></tr><tr><td><strong>结果区 / 产物</strong></td><td>产物 = 它做完交付给你的东西（文档、表格、PPT、报告、图片）。结果区 = 放这些东西的地方。</td></tr><tr><td><strong>上下文（Context）</strong></td><td>你递给它的背景资料。同一个需求，给不给上下文，质量差很多。</td></tr><tr><td><strong><code>@</code> 引用</strong></td><td>输入 <code>@</code> 弹出可选项，选中的文件就&quot;贴&quot;进需求里，等于说&quot;参考这个&quot;，不用翻路径。</td></tr><tr><td><strong>待确认</strong></td><td>它停下来等你回答。<strong>你不回话它就一直停着</strong>——这是最需要你介入的状态。</td></tr><tr><td><strong>归档 vs 删除</strong></td><td>归档 = 收起来，以后还能找到。删除 = 永久消失，恢复不了。<strong>不确定就归档。</strong></td></tr></tbody></table><blockquote><p>完整版收录 96 个术语，这里只放了 29 个最常用的。</p></blockquote><hr><h2 id="二、skill-技能" tabindex="-1">二、Skill（技能） <a class="header-anchor" href="#二、skill-技能" aria-label="Permalink to &quot;二、Skill（技能）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>术语</th><th>人话解释</th></tr></thead><tbody><tr><td><strong>Skill（技能）</strong></td><td>打包好的操作手册 + 执行脚本。<strong>类比：提示词是你每次口头交代一遍，Skill 是写成了 SOP 贴在墙上。</strong></td></tr><tr><td><strong>启用 / 关闭 / 卸载</strong></td><td>启用 = 让它干活；关闭 = 暂停，<strong>随时能开回来</strong>；卸载 = 彻底删掉，找不回来。只想让它暂时别用，用<strong>关闭</strong>。</td></tr><tr><td><strong>上传 / 查找 / 创建</strong></td><td>装 Skill 的三条路：上传 = 你已有包；查找 = 你说需求它帮你找；创建 = 现成的都不行它帮你写。新手用得最多的是<strong>查找</strong>，因为不用记名字。</td></tr><tr><td><strong>本地技能包</strong></td><td>一个 <code>.zip</code> 文件装着 Skill 全部内容。别人做好了发给你，用「上传技能」导入。</td></tr><tr><td><strong>误调用</strong></td><td>你启用了 10 个 Skill，它在你只想改错别字时顺手给你群发邮件。<strong>启用的越杂越容易发生。</strong></td></tr></tbody></table><hr><h2 id="三、专家与专家团" tabindex="-1">三、专家与专家团 <a class="header-anchor" href="#三、专家与专家团" aria-label="Permalink to &quot;三、专家与专家团&quot;">​</a></h2><table tabindex="0"><thead><tr><th>术语</th><th>人话解释</th></tr></thead><tbody><tr><td><strong>专家（Agent 型）</strong></td><td>给 AI 换一个人设和专业身份。召唤&quot;文档评审官&quot;，它就用评审官视角看稿。</td></tr><tr><td><strong>人设 + 方法论 + 工具链</strong></td><td>专家的三个组成：我是谁（人设）／我怎么做事（方法论）／我能干什么（工具链）。</td></tr><tr><td><strong>专家团</strong></td><td>多位专家 + SOP 编排。谁先做、谁后做、怎么配合。</td></tr><tr><td><strong>积分消耗倍数</strong></td><td>专家团要调多个专家多轮交互，消耗是单专家的 3–5 倍。</td></tr><tr><td><strong>专家名不可改</strong></td><td>创建后名字改不了，想换只能重建。<strong>所以别叫&quot;专家1&quot;。</strong></td></tr></tbody></table><hr><h2 id="四、连接器与-api" tabindex="-1">四、连接器与 API <a class="header-anchor" href="#四、连接器与-api" aria-label="Permalink to &quot;四、连接器与 API&quot;">​</a></h2><table tabindex="0"><thead><tr><th>术语</th><th>人话解释</th></tr></thead><tbody><tr><td><strong>连接器（Connector）</strong></td><td>把外部服务接到 WorkBuddy 上的一道门。<strong>类比：Skill 是教它做事，连接器是给它门钥匙。</strong></td></tr><tr><td><strong>授权 / 扫码授权</strong></td><td>让第三方服务同意&quot;WorkBuddy 可以代表我访问我的数据&quot;。扫一次码就等于把钥匙交出去了。</td></tr><tr><td><strong>MCP</strong></td><td>Model Context Protocol，AI 和外部工具之间的&quot;通用插头标准&quot;。</td></tr><tr><td><strong>环境变量</strong></td><td>操作系统层面的&quot;隐藏小本子&quot;，程序运行时才读，避免把密钥写死在文件里。</td></tr><tr><td><strong>解绑 vs 停止使用</strong></td><td>停止使用 = 临时关闭，<strong>授权还留着</strong>；解绑 = 撤销授权，下次要重新授权。</td></tr><tr><td><strong>权限边界三条</strong></td><td>独立授权（连一个≠连全部）／不主动抓取（不下指令就不取）／不超出已有权限（你读不到的它也读不到）。</td></tr></tbody></table><hr><h2 id="五、自动化与可靠性" tabindex="-1">五、自动化与可靠性 <a class="header-anchor" href="#五、自动化与可靠性" aria-label="Permalink to &quot;五、自动化与可靠性&quot;">​</a></h2><table tabindex="0"><thead><tr><th>术语</th><th>人话解释</th></tr></thead><tbody><tr><td><strong>自动化 / 触发</strong></td><td>到点自动跑。配置一次，按规则反复执行。</td></tr><tr><td><strong>权限模式</strong></td><td>限制无人值守任务能&quot;动&quot;多少东西的开关。<strong>默认更安全。</strong></td></tr><tr><td><strong>工作空间</strong></td><td>任务执行时所在的文件夹。自动化默认分配 <code>automation-xxxx</code> 目录。</td></tr><tr><td><strong>推送</strong></td><td>任务完成后把结果发到小程序或企业微信，不用守在电脑前。</td></tr><tr><td><strong>无人值守</strong></td><td>没人盯着自动运行。<strong>所以涉及删文件、花钱的提示词要格外谨慎。</strong></td></tr></tbody></table><hr><h2 id="想看完整版" tabindex="-1">想看完整版？ <a class="header-anchor" href="#想看完整版" aria-label="Permalink to &quot;想看完整版？&quot;">​</a></h2><p>上面 5 组共 29 个术语，是每天真正会撞到的部分。</p><p><strong>完整版收录 96 个术语</strong>，还包括：界面与菜单（不迷路）、安装与账号（第一次用）、小程序与 IM 助理（手机远程指挥）、跨章操作要点六条通则，以及第二～四篇引入的付费术语。</p><p>以上都是完整版的部分内容，完整版请看下方。</p><hr><p><em>本指南为第三方非官方整理，版权归作者所有，转载请注明出处。</em></p>',23))])}const m=a(i,[["render",h]]);export{x as __pageData,m as default};
